const input = $input.first().json;

let fields = {};
let recordId = '';

// Check all possible payload locations
const formResponse = input.form_response         // raw webhook format
  || input                                        // Typeform trigger format (already unwrapped)
  || {};

const answers = formResponse.answers
  || input.answers
  || [];

const token = formResponse.token
  || input.token
  || `submission-${Date.now()}`;

recordId = token;

if (answers.length > 0) {
  // ============================================================
  // TYPEFORM FIELD REF MAP
  // These refs are specific to the Seller Valuation Request form
  // created during template setup. If you create your own Typeform,
  // fire one test submission, inspect the answers[].field.ref
  // values in n8n's execution panel, and update this map to match.
  // ============================================================
  const refMap = {
    'c57114eb-e074-4bd8-8a47-587e5f85906b': 'sellerName',
    '272a6dd8-b438-41d3-9fdf-e2abb0e29d03': 'sellerEmail',
    '1726ff1b-c2da-499f-ae99-4a777663e2fc': 'sellerPhone',
    '0f1d33ef-9e31-414a-b453-65dba4539d75': 'propertyAddress',
    'e3fa5552-c98d-46a0-8882-63a2750307c6': 'propertyType',
    '5caf6ac4-06d3-4cff-b012-937f9884c9a5': 'bedrooms',
    '5c225bb8-5a0c-4a59-98f8-34568aa28735': 'condition',
    'fd7c0b82-15fd-45d7-a275-a901e3fd39bf': 'timeline',
    '01c7b64b-d0af-4882-97fb-17fb18d4ad9e': 'reasonForSelling',
    'b10c926e-cd63-4ce4-a8c0-b30b39ad286e': 'expectedPrice'
  };

  for (const answer of answers) {
    const ref = answer.field?.ref || '';
    const type = answer.type || '';

    let value = null;
    if (type === 'text')              value = answer.text;
    else if (type === 'email')        value = answer.email;
    else if (type === 'phone_number') value = answer.phone_number;
    else if (type === 'choice')       value = answer.choice?.label;
    else if (type === 'number')       value = String(answer.number);
    else if (type === 'long_text')    value = answer.text;

    const fieldName = refMap[ref];
    if (fieldName && value !== null) {
      fields[fieldName] = value;
    }
  }

} else {
  // Flat webhook JSON format
  const body = input.body || input;
  recordId = body.id || body.recordId || `webhook-${Date.now()}`;

  fields = {
    sellerName:       body.sellerName       || body.name    || null,
    sellerEmail:      body.sellerEmail      || body.email   || null,
    sellerPhone:      body.sellerPhone      || body.phone   || null,
    propertyAddress:  body.propertyAddress  || body.address || null,
    propertyType:     body.propertyType     || body.type    || null,
    bedrooms:         body.bedrooms         || body.beds    || null,
    bathrooms:        body.bathrooms        || body.baths   || null,
    condition:        body.condition                        || null,
    timeline:         body.timeline                         || null,
    reasonForSelling: body.reasonForSelling || body.reason  || null,
    expectedPrice:    body.expectedPrice    || body.price   || null
  };
}

return [{
  json: {
    sellerName:       fields.sellerName       || null,
    sellerEmail:      fields.sellerEmail      || null,
    sellerPhone:      fields.sellerPhone      || null,
    propertyAddress:  fields.propertyAddress  || null,
    propertyType:     fields.propertyType     || null,
    bedrooms:         fields.bedrooms         || null,
    bathrooms:        fields.bathrooms        || null,
    condition:        fields.condition        || null,
    timeline:         fields.timeline         || null,
    reasonForSelling: fields.reasonForSelling || null,
    expectedPrice:    fields.expectedPrice    || null,
    recordId,
    timestamp: new Date().toISOString()
  }
}];

