// ============================================================
// UPDATE THIS NAME IF YOU RENAME THE NODE ON THE CANVAS
const EXTRACT_NODE = 'Extract & Normalize Property Details';
// ============================================================

const propertyData = $(EXTRACT_NODE).first().json;
const inputJson = $input.first().json;

// Handle all Gemini response formats
let rawText = '';
const allItems = $input.all();

for (const item of allItems) {
  const text = item.json?.content?.parts?.[0]?.text
    || item.json?.candidates?.[0]?.content?.parts?.[0]?.text
    || item.json?.output
    || '';
  if (text && text.includes('"score"')) {
    rawText = text;
    break;
  }
}

if (!rawText) {
  rawText = inputJson.output
    || inputJson.candidates?.[0]?.content?.parts?.[0]?.text
    || (inputJson.score ? JSON.stringify(inputJson) : '')
    || '';
}

// Strip markdown fences
const cleaned = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

// Parse with fallback
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    executiveSummary: 'We have received your property details and are preparing your valuation report.',
    estimatedValueRange: 'To be determined — please schedule a consultation.',
    keyValueFactors: ['Property condition', 'Location', 'Current market conditions'],
    marketContext: 'Market conditions vary. Please contact us for a detailed analysis.',
    pricingStrategy: 'We recommend scheduling a consultation for a personalized pricing strategy.',
    recommendedNextSteps: ['Schedule a consultation', 'Prepare property documents', 'Review comparable sales'],
    score: 'Warm',
    reasoning: 'AI parsing failed — manual review recommended.',
    email_subject: 'Your Property Valuation Request',
    email_body: `Dear ${propertyData.sellerName || 'there'},\n\nThank you for submitting your property details. We have received your valuation request and will be in touch shortly with your report.`
  };
}

// HTML formatter
function escapeHtml(text) {
  if (!text) return '';
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatEmailHtml(text) {
  if (!text) return '';
  const paragraphs = text
    .split(/\n\s*\n/)
    .map(p => p.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  return paragraphs.map(p => `<p>${escapeHtml(p)}</p>`).join('');
}

// HubSpot deal stage + dynamic close date
const dealStageMap = {
  'Hot':  { stage: 'appointmentscheduled', days: 30  },
  'Warm': { stage: 'qualifiedtobuy',       days: 90  },
  'Cold': { stage: 'presentationscheduled',days: 180 }
};
const dealConfig = dealStageMap[parsed.score] || dealStageMap['Warm'];

// Google Calendar booking link
// Replace with your actual Google Calendar appointment schedule URL
const BOOKING_LINK = 'YOUR_GOOGLE_CALENDAR_BOOKING_URL';

// Build Google Docs report content
const reportContent = `Property Valuation Report
${propertyData.propertyAddress || 'Property Address Not Provided'}
Prepared: ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}

EXECUTIVE SUMMARY
${parsed.executiveSummary}

ESTIMATED VALUE RANGE
${parsed.estimatedValueRange}

KEY VALUE FACTORS
- ${(parsed.keyValueFactors || []).join('\n• ')}

MARKET CONTEXT
${parsed.marketContext}

PRICING STRATEGY
${parsed.pricingStrategy}

RECOMMENDED NEXT STEPS
1. ${(parsed.recommendedNextSteps || [])[0] || ''}
2. ${(parsed.recommendedNextSteps || [])[1] || ''}
3. ${(parsed.recommendedNextSteps || [])[2] || ''}

---
This report was prepared based on information provided by the seller 
and general market knowledge. For a full comparative market analysis, 
please schedule a consultation with your agent.`;

// Build agent notification HTML
const agentNotificationHtml = `
  <p><strong>${parsed.score === 'Hot' ? '🔥 Hot' : '📋 New'} Seller Lead</strong></p>
  <p>
    <strong>Name:</strong> ${escapeHtml(propertyData.sellerName || 'Unknown')}<br>
    <strong>Email:</strong> ${escapeHtml(propertyData.sellerEmail || 'Not provided')}<br>
    <strong>Phone:</strong> ${escapeHtml(propertyData.sellerPhone || 'Not provided')}<br>
    <strong>Property:</strong> ${escapeHtml(propertyData.propertyAddress || 'Not provided')}<br>
    <strong>Type:</strong> ${escapeHtml(propertyData.propertyType || 'Not specified')} — 
    ${escapeHtml(propertyData.bedrooms || '?')} bed / 
    ${escapeHtml(propertyData.bathrooms || '?')} bath<br>
    <strong>Condition:</strong> ${escapeHtml(propertyData.condition || 'Not specified')}<br>
    <strong>Timeline:</strong> ${escapeHtml(propertyData.timeline || 'Not specified')}<br>
    <strong>Reason:</strong> ${escapeHtml(propertyData.reasonForSelling || 'Not specified')}<br>
    <strong>Expected Price:</strong> ${escapeHtml(propertyData.expectedPrice || 'Not provided')}
  </p>
  <p>
    <strong>AI Score:</strong> ${escapeHtml(parsed.score)}<br>
    <strong>Reasoning:</strong> ${escapeHtml(parsed.reasoning)}<br>
    <strong>Estimated Value:</strong> ${escapeHtml(parsed.estimatedValueRange)}
  </p>
  <hr>
  <p>
    📄 <strong>Valuation Report:</strong> [Report link will appear here after Google Docs creation]<br>
    📅 <strong>Send Booking Link:</strong> <a href="${BOOKING_LINK}">${BOOKING_LINK}</a>
  </p>
`;

// Slack notification
const slackNotification =
  `🔥 *Hot Seller Lead*\n` +
  `*Name:* ${propertyData.sellerName || 'Unknown'}\n` +
  `*Property:* ${propertyData.propertyAddress || 'Not provided'}\n` +
  `*Timeline:* ${propertyData.timeline || 'Not specified'}\n` +
  `*Estimated Value:* ${parsed.estimatedValueRange}\n` +
  `*Score:* ${parsed.score} — ${parsed.reasoning}`;

return [{
  json: {
    // Property details
    sellerName:       propertyData.sellerName,
    sellerEmail:      propertyData.sellerEmail,
    sellerPhone:      propertyData.sellerPhone,
    propertyAddress:  propertyData.propertyAddress,
    propertyType:     propertyData.propertyType,
    bedrooms:         propertyData.bedrooms,
    bathrooms:        propertyData.bathrooms,
    condition:        propertyData.condition,
    timeline:         propertyData.timeline,
    reasonForSelling: propertyData.reasonForSelling,
    expectedPrice:    propertyData.expectedPrice,
    // AI report sections
    executiveSummary:     parsed.executiveSummary,
    estimatedValueRange:  parsed.estimatedValueRange,
    keyValueFactors:      parsed.keyValueFactors,
    marketContext:        parsed.marketContext,
    pricingStrategy:      parsed.pricingStrategy,
    recommendedNextSteps: parsed.recommendedNextSteps,
    // Qualification
    score:     parsed.score,
    reasoning: parsed.reasoning,
    // Email content
    email_subject: parsed.email_subject,
    email_body:    formatEmailHtml(parsed.email_body),
    // Google Docs report text
    reportContent,
    // HubSpot config
    hubspotDealStage: dealConfig.stage,
    closeDate: new Date(Date.now() + dealConfig.days * 86400000).getTime(),
    // Notifications
    agentNotificationHtml,
    slackNotification,
    // Metadata
    recordId:  propertyData.recordId,
    timestamp: propertyData.timestamp,
    bookingLink: BOOKING_LINK
  }
}];

// Get report content from Parse AI Output
const reportContent = $('Parse AI Output').first().json.reportContent;
const documentId = $('Create Valuation Report in Google Docs').first().json.documentId;

// Build the batchUpdate request object properly
// This avoids JSON serialization issues with newlines and special characters
const requestBody = {
  requests: [
    {
      insertText: {
        location: {
          index: 1
        },
        text: reportContent
      }
    }
  ]
};

return [{
  json: {
    documentId,
    requestBody: JSON.stringify(requestBody),
    requestBodyParsed: requestBody
  }
}];
